-- BOZO v4.15.7: expanded theoretical endgame curriculum.
-- Seeds 52 researched concept families and generates board-symmetry/file-shift training variants.
-- No side-to-move-only flips are used; generated variants preserve the chess geometry of the base study.

alter table public.endgame_positions add column if not exists concept_key text;
alter table public.endgame_positions add column if not exists variant_no integer;
alter table public.endgame_positions add column if not exists curriculum_order integer;
create index if not exists endgame_positions_concept_key_idx on public.endgame_positions(concept_key);

create or replace function pg_temp.bozo_expand_rank(r text) returns text language plpgsql as $$
declare out text=''; ch text; i int;
begin for i in 1..char_length(r) loop ch:=substr(r,i,1); if ch ~ '^[1-8]$' then out:=out||repeat('.',ch::int); else out:=out||ch; end if; end loop; return out; end $$;
create or replace function pg_temp.bozo_compress_rank(r text) returns text language plpgsql as $$
declare out text=''; n int=0; ch text; i int;
begin for i in 1..char_length(r) loop ch:=substr(r,i,1); if ch='.' then n:=n+1; else if n>0 then out:=out||n::text; n:=0; end if; out:=out||ch; end if; end loop; if n>0 then out:=out||n::text; end if; return out; end $$;
create or replace function pg_temp.bozo_swap_case(s text) returns text language plpgsql as $$
declare out text=''; ch text; i int;
begin for i in 1..char_length(s) loop ch:=substr(s,i,1); if ch ~ '^[A-Z]$' then out:=out||lower(ch); elsif ch ~ '^[a-z]$' then out:=out||upper(ch); else out:=out||ch; end if; end loop; return out; end $$;
create or replace function pg_temp.bozo_fen_variant(f text, kind text) returns text language plpgsql as $$
declare parts text[]:=regexp_split_to_array(f,' '); ranks text[]:=string_to_array(parts[1],'/'); rr text[]:=array[]::text[]; e text; i int; side text:=parts[2];
begin if kind in ('rot','vflip') then side:=case side when 'w' then 'b' else 'w' end; end if; if kind='id' then rr:=ranks; elsif kind='mirror' then for i in 1..8 loop e:=reverse(pg_temp.bozo_expand_rank(ranks[i])); rr:=array_append(rr,pg_temp.bozo_compress_rank(e)); end loop; elsif kind='rot' then for i in reverse 8..1 loop e:=reverse(pg_temp.bozo_expand_rank(ranks[i])); e:=pg_temp.bozo_swap_case(e); rr:=array_append(rr,pg_temp.bozo_compress_rank(e)); end loop; elsif kind='vflip' then for i in reverse 8..1 loop e:=pg_temp.bozo_expand_rank(ranks[i]); e:=pg_temp.bozo_swap_case(e); rr:=array_append(rr,pg_temp.bozo_compress_rank(e)); end loop; else rr:=ranks; end if; return array_to_string(rr,'/')||' '||side||' - - 0 1'; end $$;
create or replace function pg_temp.bozo_shift_fen(f text, delta int) returns text language plpgsql as $$
declare parts text[]:=regexp_split_to_array(f,' '); ranks text[]:=string_to_array(parts[1],'/'); rr text[]:=array[]::text[]; e text; i int; d int:=abs(delta);
begin if delta=0 then return f; end if; for i in 1..8 loop e:=pg_temp.bozo_expand_rank(ranks[i]); if delta>0 then if right(e,d)<>repeat('.',d) then return null; end if; e:=repeat('.',d)||left(e,8-d); else if left(e,d)<>repeat('.',d) then return null; end if; e:=right(e,8-d)||repeat('.',d); end if; rr:=array_append(rr,pg_temp.bozo_compress_rank(e)); end loop; return array_to_string(rr,'/')||' '||parts[2]||' - - 0 1'; end $$;

delete from public.endgame_positions where source_type='theory';
create temporary table bozo_endgame_seed(concept_key text,title text,category text,subcategory text,concept text,fen text,min_elo int,max_elo int,difficulty text,coach_intro text,coach_lesson text,search_aliases text,sort_no int) on commit drop;
with base_insert as (
 select title,category,subcategory,concept,fen,'theory',min_elo,max_elo,difficulty,'tablebase',coach_intro,coach_lesson,true,true,search_aliases,concept_key,1,sort_no from bozo_endgame_seed
 returning *
), cand as (
 select b.*,x.ord,x.vf from base_insert b cross join lateral (values
  (2,pg_temp.bozo_fen_variant(b.fen,'mirror')),
  (3,pg_temp.bozo_fen_variant(b.fen,'rot')),
  (4,pg_temp.bozo_fen_variant(b.fen,'vflip')),
  (5,pg_temp.bozo_shift_fen(b.fen,1)),
  (6,pg_temp.bozo_shift_fen(b.fen,-1)),
  (7,pg_temp.bozo_shift_fen(b.fen,2)),
  (8,pg_temp.bozo_shift_fen(b.fen,-2)),
  (9,pg_temp.bozo_shift_fen(pg_temp.bozo_fen_variant(b.fen,'rot'),1)),
  (10,pg_temp.bozo_shift_fen(pg_temp.bozo_fen_variant(b.fen,'rot'),-1))
 ) x(ord,vf) where x.vf is not null
), uniq as (select distinct on (concept_key,vf) * from cand order by concept_key,vf,ord)
select title||' — Training '||ord,category,subcategory,concept,vf,'theory',min_elo,max_elo,difficulty,'tablebase',coach_intro,coach_lesson,true,true,search_aliases||' '||replace(concept_key,'-',' ')||' training variant '||ord,concept_key,ord,(curriculum_order*10)+ord
from uniq on conflict (fen) do nothing;
